-- GAC.CA applications, careers, treaty register, operations, editable updates and assets.
-- Applied to the connected Supabase project as migration gac_applications_careers_and_content.
create extension if not exists pgcrypto;
alter table public.staff_profiles drop constraint if exists staff_profiles_role_check;
alter table public.staff_profiles add constraint staff_profiles_role_check check (role = any (array['admin'::text, 'editor'::text, 'visa_staff'::text]));
alter table public.staff_profiles add column if not exists roblox_username text;
alter table public.staff_profiles add column if not exists permissions jsonb not null default '{}'::jsonb;
create table if not exists public.service_applications (id uuid primary key default gen_random_uuid(), reference_code text not null unique default ('GAC-' || upper(substr(encode(gen_random_bytes(8), 'hex'), 1, 10))), application_type text not null check (application_type = any (array['visa'::text,'passport_first'::text,'passport_renewal'::text,'passport_replacement'::text,'emergency_travel_document'::text])), applicant_name text not null, roblox_username text not null, discord_username text, country_of_residence text not null, fictional_birth_date date, purpose text not null, form_data jsonb not null default '{}'::jsonb, status text not null default 'submitted' check (status = any (array['submitted'::text,'reviewing'::text,'validated'::text,'denied'::text])), review_note text, reviewed_by uuid references auth.users(id) on delete set null, assigned_staff_id uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), reviewed_at timestamptz);
create index if not exists service_applications_status_created_idx on public.service_applications(status, created_at desc);
create index if not exists service_applications_roblox_idx on public.service_applications(lower(roblox_username));
create table if not exists public.career_listings (id uuid primary key default gen_random_uuid(), title text not null, department text not null, summary text not null default '', description text not null default '', requirements text not null default '', location text not null default '', openings integer not null default 1 check (openings >= 0), status text not null default 'open' check (status = any (array['open'::text,'closed'::text,'draft'::text])), image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), updated_by uuid references auth.users(id) on delete set null);
create table if not exists public.career_applications (id uuid primary key default gen_random_uuid(), reference_code text not null unique default ('JOB-' || upper(substr(encode(gen_random_bytes(8), 'hex'), 1, 10))), career_id uuid not null references public.career_listings(id) on delete restrict, applicant_name text not null, roblox_username text not null, discord_username text, country_of_residence text not null, fictional_birth_date date, answers jsonb not null default '{}'::jsonb, status text not null default 'submitted' check (status = any (array['submitted'::text,'reviewing'::text,'validated'::text,'denied'::text])), review_note text, reviewed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), reviewed_at timestamptz);
create index if not exists career_applications_status_created_idx on public.career_applications(status, created_at desc);
create table if not exists public.treaties (id uuid primary key default gen_random_uuid(), country text not null, title text not null, category text not null default 'Agreement', signed_on date, status text not null default 'active' check (status = any (array['active'::text,'suspended'::text,'expired'::text])), summary text not null default '', body text not null default '', map_country_code text, published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), updated_by uuid references auth.users(id) on delete set null);
create index if not exists treaties_country_idx on public.treaties(lower(country));
create table if not exists public.active_operations (id uuid primary key default gen_random_uuid(), title text not null, country text not null, category text not null check (category = any (array['diplomatic_mission'::text,'conflict'::text,'military'::text,'humanitarian'::text,'other'::text])), status text not null default 'active' check (status = any (array['active'::text,'concluded'::text,'suspended'::text])), summary text not null default '', public_details text not null default '', latitude double precision, longitude double precision, published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), updated_by uuid references auth.users(id) on delete set null);
create table if not exists public.site_updates (id uuid primary key default gen_random_uuid(), title text not null, department text not null default 'Global Affairs Canada', summary text not null default '', body text not null default '', image_url text, image_alt text not null default '', link_url text, published boolean not null default false, published_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), updated_by uuid references auth.users(id) on delete set null);
create table if not exists public.citizen_profiles (id uuid primary key references auth.users(id) on delete cascade, roblox_username text not null, discord_username text, fictional_name text not null, fictional_birth_date date, country_of_origin text not null, account_purpose text not null, profile_image_url text, status text not null default 'pending' check (status = any (array['pending'::text,'validated'::text,'denied'::text])), review_note text, reviewed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index if not exists citizen_profiles_roblox_lower_idx on public.citizen_profiles(lower(roblox_username));
alter table public.service_applications enable row level security;
alter table public.career_listings enable row level security;
alter table public.career_applications enable row level security;
alter table public.treaties enable row level security;
alter table public.active_operations enable row level security;
alter table public.site_updates enable row level security;
alter table public.citizen_profiles enable row level security;
drop policy if exists "Published careers are public" on public.career_listings;
create policy "Published careers are public" on public.career_listings for select to anon, authenticated using (status = 'open');
drop policy if exists "Active treaties are public" on public.treaties;
create policy "Active treaties are public" on public.treaties for select to anon, authenticated using (published = true);
drop policy if exists "Published operations are public" on public.active_operations;
create policy "Published operations are public" on public.active_operations for select to anon, authenticated using (published = true);
drop policy if exists "Published site updates are public" on public.site_updates;
create policy "Published site updates are public" on public.site_updates for select to anon, authenticated using (published = true);
drop policy if exists "Staff can read service applications" on public.service_applications;
create policy "Staff can read service applications" on public.service_applications for select to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role in ('admin','visa_staff')));
drop policy if exists "Admins can update service applications" on public.service_applications;
create policy "Admins can update service applications" on public.service_applications for update to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin')) with check (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
drop policy if exists "Visa staff can update service applications" on public.service_applications;
create policy "Visa staff can update service applications" on public.service_applications for update to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'visa_staff')) with check (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'visa_staff'));
drop policy if exists "Staff can read career applications" on public.career_applications;
create policy "Staff can read career applications" on public.career_applications for select to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
drop policy if exists "Admins can update career applications" on public.career_applications;
create policy "Admins can update career applications" on public.career_applications for update to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin')) with check (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
drop policy if exists "Admins manage career listings" on public.career_listings;
create policy "Admins manage career listings" on public.career_listings for all to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin')) with check (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
drop policy if exists "Admins manage treaties" on public.treaties;
create policy "Admins manage treaties" on public.treaties for all to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin')) with check (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
drop policy if exists "Admins manage operations" on public.active_operations;
create policy "Admins manage operations" on public.active_operations for all to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin')) with check (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
drop policy if exists "Admins manage site updates" on public.site_updates;
create policy "Admins manage site updates" on public.site_updates for all to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin')) with check (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
drop policy if exists "Citizens can read own profile" on public.citizen_profiles;
create policy "Citizens can read own profile" on public.citizen_profiles for select to authenticated using (id = auth.uid());
drop policy if exists "Citizens can update limited own profile" on public.citizen_profiles;
create policy "Citizens can update limited own profile" on public.citizen_profiles for update to authenticated using (id = auth.uid() and status <> 'validated') with check (id = auth.uid() and status <> 'validated');
drop policy if exists "Admins manage citizen profiles" on public.citizen_profiles;
create policy "Admins manage citizen profiles" on public.citizen_profiles for all to authenticated using (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin')) with check (exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('gac-public-assets', 'gac-public-assets', true, 15728640, array['image/jpeg','image/png','image/webp','image/svg+xml','application/pdf']) on conflict (id) do update set public = true, file_size_limit = 15728640, allowed_mime_types = excluded.allowed_mime_types;
drop policy if exists "Public can view GAC assets" on storage.objects;
create policy "Public can view GAC assets" on storage.objects for select to anon, authenticated using (bucket_id = 'gac-public-assets');
drop policy if exists "Admins can upload GAC assets" on storage.objects;
create policy "Admins can upload GAC assets" on storage.objects for insert to authenticated with check (bucket_id = 'gac-public-assets' and exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
drop policy if exists "Admins can update GAC assets" on storage.objects;
create policy "Admins can update GAC assets" on storage.objects for update to authenticated using (bucket_id = 'gac-public-assets' and exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin')) with check (bucket_id = 'gac-public-assets' and exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
drop policy if exists "Admins can delete GAC assets" on storage.objects;
create policy "Admins can delete GAC assets" on storage.objects for delete to authenticated using (bucket_id = 'gac-public-assets' and exists (select 1 from public.staff_profiles sp where sp.id = auth.uid() and sp.active = true and sp.role = 'admin'));
